def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    cell_names = [[f"{chr(65 + c)}{r}" for c in range(26)] for r in range(100)]
    results: dict[str, int | str] = {}
    formulas: dict[str, str] = {}

    for name, content in cells.items():
        s = content.strip()
        if s.startswith("="):
            formulas[name] = s[1:]
        else:
            results[name] = int(s)

    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif ch.isalpha():
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", word))
                i = j
            elif s[i : i + 2] in ("<=", ">=", "<>"):
                tokens.append(("OP", s[i : i + 2]))
                i += 2
            elif ch in ("=", "<", ">"):
                tokens.append(("OP", ch))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", None))
        return tokens

    def parse_formula(s: str):
        tokens = tokenize(s)
        pos = 0

        def parse_expr():
            nonlocal pos
            node = parse_mul()
            while tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_mul()
                node = ("bin", op, node, right)
            return node

        def parse_mul():
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("bin", op, node, right)
            return node

        def parse_unary():
            nonlocal pos
            neg = False
            while tokens[pos][0] == "-":
                neg = not neg
                pos += 1
            node = parse_atom()
            return ("neg", node) if neg else node

        def parse_atom():
            nonlocal pos
            kind, val = tokens[pos]
            if kind == "NUM":
                pos += 1
                return ("num", val)
            if kind == "CELL":
                pos += 1
                return ("cell", val)
            if kind == "(":
                pos += 1
                node = parse_expr()
                pos += 1  # ')'
                return node
            fn = val
            pos += 2  # FUNC and '('
            if fn == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1  # ','
                then_e = parse_expr()
                pos += 1  # ','
                else_e = parse_expr()
                pos += 1  # ')'
                return ("if", op, left, right, then_e, else_e)
            args = []
            while True:
                if tokens[pos][0] == "CELL" and tokens[pos + 1][0] == ":":
                    c1_str = tokens[pos][1]
                    c2_str = tokens[pos + 2][1]
                    pos += 3
                    c1 = ord(c1_str[0]) - 65
                    r1 = int(c1_str[1:])
                    c2 = ord(c2_str[0]) - 65
                    r2 = int(c2_str[1:])
                    if r1 > r2:
                        r1, r2 = r2, r1
                    if c1 > c2:
                        c1, c2 = c2, c1
                    args.append(("range", r1, r2, c1, c2))
                else:
                    args.append(("expr", parse_expr()))
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    pos += 1  # ')'
                    break
            return ("agg", fn, args)

        return parse_expr()

    def iter_agg_nodes(args):
        for arg in args:
            if arg[0] == "range":
                _, r1, r2, c1, c2 = arg
                for r in range(r1, r2 + 1):
                    row_names = cell_names[r]
                    for c in range(c1, c2 + 1):
                        cname = row_names[c]
                        if cname in cells:
                            yield ("cell", cname)
            else:
                yield arg[1]

    in_progress: set[str] = set()

    def advance_agg(fn, it, acc, stack):
        while True:
            nxt = next(it, None)
            if nxt is None:
                return None, 0 if acc is None else acc
            if nxt[0] == "cell":
                cname = nxt[1]
                if cname not in cells:
                    v: int | str = 0
                elif cname in results:
                    v = results[cname]
                elif cname in in_progress:
                    v = "#CYCLE!"
                else:
                    stack.append(("agg", fn, it, acc))
                    return nxt, 0
                if isinstance(v, str):
                    return None, v
                if fn == "SUM":
                    acc += v
                elif acc is None or (v < acc if fn == "MIN" else v > acc):
                    acc = v
            else:
                stack.append(("agg", fn, it, acc))
                return nxt, 0

    for root in cells:
        if root in results:
            continue

        in_progress.add(root)
        stack: list = [("cell_done", root)]
        cur_node = parse_formula(formulas[root])
        val: int | str = 0

        while True:
            while cur_node is not None:
                kind = cur_node[0]
                if kind == "num":
                    val = cur_node[1]
                    cur_node = None
                elif kind == "cell":
                    cname = cur_node[1]
                    if cname not in cells:
                        val = 0
                        cur_node = None
                    elif cname in results:
                        val = results[cname]
                        cur_node = None
                    elif cname in in_progress:
                        val = "#CYCLE!"
                        cur_node = None
                    else:
                        in_progress.add(cname)
                        stack.append(("cell_done", cname))
                        cur_node = parse_formula(formulas[cname])
                elif kind == "neg":
                    stack.append(("neg",))
                    cur_node = cur_node[1]
                elif kind == "bin":
                    _, op, left, right = cur_node
                    stack.append(("bin_l", op, right))
                    cur_node = left
                elif kind == "if":
                    _, op, left, right, then_e, else_e = cur_node
                    stack.append(("if_l", op, right, then_e, else_e))
                    cur_node = left
                else:  # "agg"
                    _, fn, args = cur_node
                    it = iter_agg_nodes(args)
                    acc = 0 if fn == "SUM" else None
                    cur_node, val = advance_agg(fn, it, acc, stack)

            while cur_node is None:
                if not stack:
                    break
                frame = stack.pop()
                tag = frame[0]
                if tag == "cell_done":
                    cname = frame[1]
                    in_progress.remove(cname)
                    results[cname] = val
                elif tag == "neg":
                    if not isinstance(val, str):
                        val = -val
                elif tag == "bin_l":
                    if not isinstance(val, str):
                        _, op, right = frame
                        stack.append(("bin_r", op, val))
                        cur_node = right
                elif tag == "bin_r":
                    if not isinstance(val, str):
                        _, op, lval = frame
                        if op == "+":
                            val = lval + val
                        elif op == "-":
                            val = lval - val
                        elif op == "*":
                            val = lval * val
                        else:  # "/"
                            if val == 0:
                                val = "#DIV/0!"
                            elif (lval < 0) ^ (val < 0):
                                val = -(abs(lval) // abs(val))
                            else:
                                val = abs(lval) // abs(val)
                elif tag == "if_l":
                    if not isinstance(val, str):
                        _, op, right, then_e, else_e = frame
                        stack.append(("if_r", op, val, then_e, else_e))
                        cur_node = right
                elif tag == "if_r":
                    if not isinstance(val, str):
                        _, op, lval, then_e, else_e = frame
                        if op == "=":
                            cond = lval == val
                        elif op == "<>":
                            cond = lval != val
                        elif op == "<":
                            cond = lval < val
                        elif op == "<=":
                            cond = lval <= val
                        elif op == ">":
                            cond = lval > val
                        else:  # ">="
                            cond = lval >= val
                        cur_node = then_e if cond else else_e
                else:  # "agg"
                    if not isinstance(val, str):
                        _, fn, it, acc = frame
                        if fn == "SUM":
                            acc += val
                        elif acc is None or (val < acc if fn == "MIN" else val > acc):
                            acc = val
                        cur_node, val = advance_agg(fn, it, acc, stack)

            if cur_node is None and not stack:
                break

    return results
